// Source type5/color0..15/radius4; type32/color0..3/radius14.
const TH18_BALL2: int = 432;
const TH18_BUBBLE: int = 864;

// TH18 v1.00a st01bs::BossCard2, source505-696. Shell source t0=card124.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;

// Source STEP(30,1,c0,d0,angle-offset0,target-speed0), then ANGLE_ACCEL100.
// This single segment has fixed logical speed2.5, no concurrent modification or later logical-speed read.
// t0..29:2.5*(1-t/30); t30:0 then same-tick first +gain; t130:gain stops.
xformdef MAIN_MOTION(gain: fx) {
    @30 step_speed(0fx, 30);
    @100 set_accel(gain);
    set_accel(0fx);
}
sub emit_ring(a: angle, ox: fx, oy: fx, n: int, color: int, gain: fx) {
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, color);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_angle(0, a, 0deg); // Source mode3; ang2 is layer rotation and M1 ignores it.
    sh_speed(0, 2.5fx, 0fx);
    sh_offset(0, ox, oy);
    sh_dist(0, -10fx); // ANIM a1 also retreats4*velocity; other birth-stage behavior omitted.
    sh_xform(0, MAIN_MOTION(gain));
    sh_fire(0); // M1 source layer-outer/ray-inner order equals target ring order.
}
sub main_group(a: angle, ox: fx, oy: fx, n: int, until: int) {
    for i in 0..7 {
        if $frame >= until { return; }
        var color: int = 2;
        if i == 0 { color = 4; }
        if i == 1 { color = 6; }
        if i == 2 { color = 8; }
        if i == 3 { color = 11; }
        if i == 4 { color = 13; }
        if i == 5 { color = 14; }
        var gain: fx = (1.2fx+(i as fx)*0.5fx)/100;
        emit_ring(a, ox, oy, n, color, gain);
        if i < 6 { card_wait(3); } // Last color has no trailing wait:18frames per group.
    }
}
async sub bubbles() {
    // Source async first runs next frame; no older async survives across the>=268frame cycle.
    var rank: int = global(GVAR_RANK);
    var n: int = 3;
    var delta: int = 5461; //30deg nearest BAM.
    if rank == 2 { n = 5; }
    if rank == 3 { n = 7; delta = 3641; } //20deg nearest BAM.
    var aim: angle = aim_player();
    sh_reset(1);
    sh_sprite(1, TH18_BUBBLE, 3);
    sh_count(1, 1, 1);
    sh_speed(1, 0.6fx, 0fx);
    sh_dist(1, -2.4fx);
    // Preserve source mode0 creation order:center,-1,+1,-2,+2,...
    for i in 0..n {
        var off: int = ((i+1)/2)*delta;
        if i%2 != 0 { off = -off; }
        sh_angle(1, aim+(off as angle), 0deg);
        sh_fire(1);
    }
    wait(60); // This async wait never blocks the main ring task or advances its movement helper.
}
async sub pattern() {
    wait(120);
    var until: int = $frame+SOURCE_LIMIT;
    set_self_int(1, until);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    var rank: int = global(GVAR_RANK);
    var n: int = 16;
    if rank == 0 { n = 12; }
    var groups: int = 3;
    var tail: int = 180;
    if rank == 1 { tail = 160; }
    if rank == 2 { groups = 6; tail = 100; }
    if rank == 3 { groups = 8; tail = 90; }
    wait(90);
    loop {
        if $frame >= until { return; }
        card_wait(60);
        for group in 0..groups {
            if $frame >= until { return; }
            var ox: fx = 0fx;
            var oy: fx = 0fx;
            if group < 2 {
                var u: fx = (rand(65536)-32768) as fx / 65536 + 0.5fx;
                if group == 0 { ox = u*64fx+32fx; }
                else { ox = u*(-64fx)-32fx; }
            } else {
                var signed_u: fx = (rand(65536)-32768) as fx / 32768;
                ox = signed_u*(-64fx);
                oy = 60fx;
            }
            var a: angle = 0deg;
            if group == 2 { a = aim_player(); } // Snapshot from boss, not from the offset origin.
            else { a = (rand(65536)-32768) as angle; }
            main_group(a, ox, oy, n, until);
            if $frame >= until { return; }
            if group == 2 && rank > 0 { spawn bubbles(); }
        }
        if $frame >= until { return; }
        card_move_rand();
        card_wait(tail);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    spell_begin(0, 4, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard2 only. int slot0=next-step count, int1=source end card-frame; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
